"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1476],{51476:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-pce-avgust-stavka-frs","locale":"zh","title":"美国八月通胀低于预期，但部分放缓来自统计重算","description":"美国八月通胀3.4%，低于3.7%预测。美联储并未降息，市场只把十月加息概率降至35%；解释统计修订的作用。","blocks":[{"id":"b001","kind":"paragraph","text":"美国商务部2026年九月30日公布八月通胀：同比3.4%，预期3.7%。剔除波动较大的食品和能源后为3%，预期3.3%。这是美国央行美联储首要关注的PCE指标，目标2%。"},{"id":"b002","kind":"paragraph","text":"数字立即改变市场预期。美联储九月自2023年以来首次加息至3.75–4%。新数据后，十月27–28日再次加息概率从约45%降至35%。这并非转向廉价资金：美联储既无降息打算也未承诺，只是市场对再加一次没那么确信。"},{"id":"b003","kind":"paragraph","text":"但剔除食品能源后的放缓来自统计。美国经济分析局改变法律服务、软件和投资管理价格计算，自2021年起重算，类似商店换秤后重算旧账单，顾客付同样的钱，账面却“便宜”。这叫历史修订。它把七月核心通胀下调0.36个百分点，从约3.3%降至3%，意味着八月并非下降，而是持平。"},{"id":"b004","kind":"paragraph","text":"美国经济并未减速。2026年第二季度GDP增速由1.5%上修至2.2%，八月居民支出增速为一年最快。明尼阿波利斯联储主席卡什卡利称约3%的通胀“仍过高”，已超过目标逾5年，新数据几乎没改变整体判断。"},{"id":"b005","kind":"paragraph","text":"因此美国贷款并未变便宜。10年期国债收益率升至约5.3%，房贷以此定价。俄罗斯受到的渠道是美元，而美元仍稳：美债收益超过5%，美元资金仍贵。十月1日官方汇率83.56卢布兑美元，较前日低87戈比。卢布走强是内部因素：季末出口商卖汇，中国一周假期前进口商暂缓采购。"},{"id":"b006","kind":"paragraph","text":"未知之处：八月数据尚不包括伊朗战争引起的九月燃料涨价，下份报告可能重新推动加息讨论。持美元者若因通胀放缓新闻卖出，是相信一个很大程度来自重算的数字；若押注继续加息买入，则是在赌尚无人见过的报告。"},{"id":"b007","kind":"heading","text":"美国2026年八月通胀是多少？"},{"id":"b008","kind":"paragraph","text":"美联储首要PCE指标同比3.4%，预期3.7%。剔除食品能源为3%，预期3.3%；美联储目标2%。"},{"id":"b009","kind":"heading","text":"美联储会在2026年十月加息吗？"},{"id":"b010","kind":"paragraph","text":"八月数据后市场估计约35%，此前45%。当前区间3.75–4%，将在十月27–28日决定。"},{"id":"b011","kind":"heading","text":"美国通胀为何低于预期？"},{"id":"b012","kind":"paragraph","text":"部分因为方法改变。统计部门自2021年重算法务、软件和投资管理价格，令七月核心通胀降低0.36个百分点，从约3.3%至3%。"}],"sources":[{"label":"美联储偏好的指标显示八月核心通胀3.0%","url":"https://www.cnbc.com/2026/09/30/feds-preferred-gauge-showed-core-inflation-at-3point0percent-in-august-much-lighter-than-expected.html"},{"label":"明尼阿波利斯联储主席卡什卡利访谈","url":"https://www.cnbc.com/2026/09/30/watch-minneapolis-fed-president-neel-kashkari.html"},{"label":"美国通胀报告利好，提高美联储不加息概率","url":"https://www.theguardian.com/business/2026/sep/30/inflation-report-interest-rates-fed"},{"label":"PCE通胀放缓至3.4%，削弱再次加息理由","url":"https://finance.yahoo.com/economy/policy/article/pce-inflation-eases-to-34--cooling-the-case-for-another-fed-rate-hike-125513195.html"},{"label":"PCE物价指数下修","url":"https://finance.yahoo.com/economy/articles/pce-price-index-revised-down-123741659.html"},{"label":"美联储偏好的通胀指标低于预期","url":"https://finance.yahoo.com/economy/articles/feds-preferred-inflation-metric-came-163426036.html"},{"label":"美联储偏好的通胀指标下降","url":"https://finance.yahoo.com/economy/policy/articles/feds-preferred-inflation-gauge-declined-174601544.html"},{"label":"美联储偏好通胀指标上涨3.4%","url":"https://finance.yahoo.com/economy/policy/articles/fed-preferred-measure-inflation-rose-124249351.html"},{"label":"通胀数据较温和后黄金持稳","url":"https://finance.yahoo.com/markets/commodities/articles/gold-steady-softer-inflation-data-000816044.html"},{"label":"卡什卡利称通胀超出油价冲击","url":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html"},{"label":"官方美元汇率跌破84卢布","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"2026年十月1日美元、欧元和人民币汇率：卢布为何走强","url":"https://www.vbr.ru/novosti/kursy-valyut/2026/09/30/kurs-valut-na-1-oktyabrya/"},{"label":"美联储会议日历与信息","url":"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm"}],"sourceBodySha256":"1145a94c8144e6d38a235e40e919942738f6348f62bad69c60f81ff17dc4c1a0"}')}}]);